#!/bin/bash
# Apply one bug at a time and check that the tests catch it.
cd "${SLURM_SUBMIT_DIR:-$PWD}"
export PYTHONDONTWRITEBYTECODE=1  # a reverted mutant can keep its size and mtime, so a stale .pyc would be reused
mutate() {  # file, sed expression, label
    cp "$1" "$1.bak"; sed -i "$2" "$1"
    if cmp -s "$1" "$1.bak"; then echo "NOT APPLIED: $3"
    elif /home/iury/.pixi/bin/pixi run pytest -q -x tests >/dev/null 2>&1; then echo "SURVIVED: $3"
    else echo "caught: $3"; fi
    mv "$1.bak" "$1"
}
mutate app/swot_view.py 's/    return out.isel(time=(count >= min_pixels).values)/    return out/' "point series keeps passages with too few pixels"
mutate app/swot_view.py 's/    near = sub\[var\].where(distance(sub.latitude, sub.longitude, lat, lon) <= radius)/    near = sub[var]/' "point series averages the whole cut"
mutate app/swot_view.py 's/sel(time=slice("{start}", "{end}")/sel(time=slice("{start}", None)/' "snippet ignores the end date"
mutate app/swot_view.py 's/    width = (east - west) % 360 or 360  # west == east/    width = (east - west) % 360  # west == east/' "a -180 to 180 box is empty"
mutate app/server.py 's/Image.fromarray(rgba\[::-1\])/Image.fromarray(rgba)/' "tiles upside down"
mutate app/server.py 's/    x0, y1 = -WORLD \/ 2 + x \* size, WORLD \/ 2 - y \* size/    x0, y1 = -WORLD \/ 2 + x * size, WORLD \/ 2 - (y + 1) * size/' "tiles one row off"
mutate app/server.py 's/per_day = over.cycle.to_series().groupby(over.time.to_index().floor("D"))/per_day = index.cycle.to_series().groupby(index.time.to_index().floor("D"))/' "timeline ignores the box"
mutate app/server.py 's/    lon = np.unwrap(lon, period=360, axis=1)/    pass/' "swaths torn at 180"
mutate app/server.py 's/            rows = slice(a, b)/            rows = usable/' "lines across land joined into one mesh"
mutate app/server.py 's/    return load(west, east, south, north, start, int(np.clip(days, 1, MAX_DAYS)), variable)\[0\]/    return next(reversed(loaded.values()))/' "tiles drawn from whatever view is in memory"
mutate app/swot_view.py 's/    lons = "" if (east - west) % 360 == 0 else/    lons = "" if False else/' "global code keeps the longitude filter"
mutate app/server.py 's/str(pd.Timestamp(data.line_time\[i, line\]).round("s"))/str(pd.Timestamp(data.sub.time.values[i]).round("s"))/' "click gives the passage's mean time, not its line's"
mutate app/server.py 's/lines = slice(rows.start + block.start, /lines = slice(rows.start, /' "click takes the line from the wrong block"
mutate app/server.py 's/hit = (x1 + shift >= x_range\[0\]) \& (x0 + shift <= x_range\[1\])/hit = (x1 >= x_range[0]) \& (x0 <= x_range[1])/' "copies of the world east and west not drawn"
mutate app/server.py 's/            if len(above) == 0 or len(below) == 0:/            if len(np.intersect1d(above, below)) == 0:/' "a click between two lines finds no data"
mutate app/server.py 's/    angles = np.arccos(np.clip((v\[:-1\] \* v\[1:\]).sum(-1), -1, 1))  # of each segment/    angles = np.deg2rad(np.hypot(np.diff(lon), np.diff(lat)))  # of each segment/' "transect segments measured in degrees, not along great circles"
mutate app/server.py 's/d, j = tree.query(pts, distance_upper_bound=radius \/ swot_view.EARTH_RADIUS)/d, j = tree.query(pts)/' "transect fills the nadir gap and beyond the swath"
mutate app/server.py 's/        t = pd.Timestamp(data.line_time\[i, seen\[len(seen) \/\/ 2\]\]).round("s")/        t = pd.Timestamp(data.sub.time.values[i]).round("s")/' "transect gives the passage's mean time"
mutate app/server.py 's/    dist = np.r_\[np.arange(0, length, step), length\]  # and the last vertex/    dist = np.arange(0, length, step)/' "transect stops short of its last vertex"
mutate app/server.py 's/        times = data.line_time\[i, rows\[i\].clip(0)\]/        times = data.line_time[i, np.full_like(rows[i], seen[len(seen) \/\/ 2])]/' "transect gives every point the time of the middle line"
mutate app/swot_view.py 's/get_repo("{target.removeprefix("arraylake:")}")/get_repo("{target}")/' "Arraylake code asks for the wrong repository name"
mutate app/swot_view.py 's/        min_pixels = max(1, round(np.pi \* radius\*\*2 \/ 4 \/ 4))/        min_pixels = 5/' "a 2 km time series drops every passage"
mutate app/server.py 's/    at = \[np.repeat(times, len(hit)) for _, times, hit, \*_ in found\]/    at = [np.repeat(times[:1], len(hit) * len(times)) for _, times, hit, *_ in found]/' "Hovmoller gives every passage the first one's values"
mutate app/server.py 's/        d, j = cKDTree(unit(lo\[ok\], la\[ok\])).query(pts, distance_upper_bound=1.5 \/ swot_view.EARTH_RADIUS)/        d, j = cKDTree(unit(lo[ok], la[ok])).query(pts)/' "Hovmoller fills points off the swath"
mutate app/swot_view.py 's/near = ({value}).where(d <= radius)/near = ({value}).where(d <= 3 * radius)/' "series code averages a wider circle than the app"
mutate app/swot_view.py 's/query(samples, distance_upper_bound=1.5 \/ R)/query(samples)/' "line code fills points off the swath"
mutate app/swot_view.py 's/    window = f/    window = "" and f/' "line code profile ignores the dates"
mutate app/server.py 's/        values\[k, first:first + len(q\["value"\])\] = /        values[k, :len(q["value"])] = /' "chart NetCDF puts a passage's values at the line's start"
mutate app/swot_view.py 's/        lon_max\[k\] = nadir.longitude_nadir.values + dlon/        lon_max[k] = nadir.longitude_nadir.values + dlon \/ 2/' "nadir envelope only half the swath to the east"
mutate app/swot_view.py 's/        return \[int(k) async for k in store.list_dir("line_time\/c")\]/        return [int(k) async for k in store.list_dir("line_time\/c")][:1]/' "written passages: only the first"
mutate app/swot_view.py 's/    per = ds.line_time.encoding\["chunks"\]\[0\]/    per = 1/' "written passages: chunk indices taken as passages"
mutate app/server.py 's/        lon, lat = across(lon), across(lat)  # meshes need every corner/        pass  # meshes need every corner/' "L2 Unsmoothed: nothing drawn where the gap has no position"
mutate app/server.py 's/        step = (a1 - a0 + 180) % 360 - 180/        step = a1 - a0/' "gap positions interpolated around the world across 180"
mutate app/server.py 's/    tiles.shift\["shifted"\] = shift/    tiles.shift["shifted"] = shift * 0/' "detail tiles not shifted like the base"
mutate app/server.py 's/    if detail is None or z < DETAIL_ZOOM - 1 or names is None:/    if detail is None or names is None:/' "detail tiles at every zoom"
mutate app/server.py 's/        return a\[:, k \/\/ 2::k, k \/\/ 2::k\]\[:, :rows \/\/ k, :cols \/\/ k\]/        return a[:, ::k, ::k][:, :rows \/\/ k, :cols \/\/ k]/' "coarse blocks drawn at their corner (half a block off)"
mutate app/server.py 's/    return values if flag is None else np.where(flag == 0, values, np.nan)/    return values/' "L2 values drawn where the quality flag is bad"
mutate app/server.py 's/np.full(len(values), np.median(inside) if len(inside) else np.nan, "float32")/np.full(len(values), np.mean(inside) if len(inside) else np.nan, "float32")/' "the box's mean (one absurd pixel moves every color)"
mutate app/server.py 's/"passage": np.array(\[np.nanmedian(v) for v in per\], "float32")}/"passage": np.array([np.nanmean(v) for v in per], "float32")}/' "each passage's mean (one absurd pixel moves its colors)"
mutate app/server.py 's/        pixel = (x_range\[1\] - x_range\[0\]) \/ width \* np.cos(2 \* np.arctan(np.exp(np.mean(y_range) \/ R)) - np.pi \/ 2)/        pixel = (x_range[1] - x_range[0]) \/ width \/ 16/' "coarse levels chosen 16 times too fine"
mutate app/server.py 's/vs.append(self.value(mode, i, lines).ravel())/vs.append(self.value(mode, i).ravel()[:x.size])/' "cells as points take values of the wrong lines"
mutate app/server.py 's/    near = slice(max(near\[0\] - 1, 0), near\[-1\] + 2)/    near = slice(near[0], near[-1] + 1)/' "detail tiles without the cells across their edges"
mutate app/server.py 's/(east + 180) % 360 - 180, south - 0.7, north + 0.7))/(east + 180) % 360 - 180, south, north))/' "detail tiles miss the passes whose lines only lean into them"
mutate app/swot_view.py 's/        return np.flatnonzero(ds.written.values == 1)/        return np.flatnonzero(ds.written.values > 0)/' "passages skipped by the build (no position) taken as written"
mutate app/server.py 's/    out = {a: np.stack(parts\[j \* n:(j + 1) \* n\]) if n else/    out = {a: np.stack(parts[:n]) if n else/' "a view read in parallel takes the first array for every one"
mutate app/server.py 's/    return \[READ_AHEAD.submit(detail_block, i, c, tuple(names)) for i, c in jobs\]/    return []/' "the detail of a region not read ahead"
mutate app/server.py 's/        value\[hit\] = values\[k\].ravel()\[flat\] - per.get((cycle, pass_id), box)/        value[hit] = values[k].ravel()[flat[::-1]] - per.get((cycle, pass_id), box)/' "250 m profile takes the pixels in the wrong order"
mutate app/server.py 's/query(pts, distance_upper_bound=FINE_RADIUS \/ swot_view.EARTH_RADIUS)/query(pts, distance_upper_bound=1.5 \/ swot_view.EARTH_RADIUS)/' "250 m profile takes pixels 1.5 km away"
mutate app/server.py 's/    times, rows, chunks = detail_lines(\*line_box(lon, lat), start, days)/    times, rows, chunks = detail_lines(*line_box(lon, lat), "2024-01-01", 30)/' "250 m profile ignores the dates of the view"
mutate app/server.py 's/        v = np.where(swot_view.distance(la, lo, lat, lon) <= radius, values, np.nan)/        v = values/' "250 m series averages the whole cut"
mutate app/server.py 's/    if fine and dist\[-1\] > FINE_LENGTH:/    if False:/' "250 m Hovmoller on lines of any length"
mutate app/server.py 's/    product, src = (DETAIL_PRODUCT, detail) if fine else (PRODUCT, base)/    product, src = (PRODUCT, base)/' "250 m Hovmoller reads the base store"
mutate app/swot_view.py 's/^fine = point_series(fine, /^fine = point_series(ds, /' "series code: the finer series from the base store"
